// Ports quest-app/Tests~/Program.cs at 6017fc2 and MeshTests.cs at 281c614.
// Goldens generated by /tmp/m1a-parity/Parity.cs referencing unchanged C# sources,
// .NET 8 Release, GreedyMesher f0583fd / SectionBatches 281c614. Light/biomes
// disabled in C# for M1 flat-colour parity; full M3 shading is excluded.
import Foundation
import Testing
@testable import TabletopCore

private func m1aMeshes(_ w: WorldModel, specials: Bool = true) -> [MeshData] {
    SectionPlan.keys(w.sectionCount).map { k in
        var m = MeshData(); GreedyMesher.build(w,k,&m)
        if specials { GreedyMesher.buildSpecials(w,k,&m) }; return m
    }
}
private func m1aBenchmark(_ name: String, _ w: WorldModel, specials: Bool) {
    guard ProcessInfo.processInfo.environment["M1A_BENCHMARK"] == "1" else { return }
    for _ in 0..<10 { _ = m1aMeshes(w,specials: specials) }
    let start = ContinuousClock.now
    var vertices = 0
    for _ in 0..<100 { vertices += m1aMeshes(w,specials: specials).reduce(0) { $0+$1.verts.count } }
    let d = start.duration(to: .now).components
    print("M1A \(name) ms=\((Double(d.seconds)*1000+Double(d.attoseconds)/1e15)/100) vertices=\(vertices)")
}

@Suite struct MeshParityTests {
    @Test func syntheticCanonicalCSharpGoldens() {
        let a = "minecraft:air", s = "minecraft:stone"
        let cases: [(String, WorldModel, Int, String)] = [
            ("cube",m1aWorld(Int3(4,4,4)) { _,_,_ in 1 },6,"82a8833277895cf5"),
            ("checker",m1aWorld(Int3(4,1,4),palette: [a,s,"minecraft:dirt"]) { x,_,z in 1+((x+z)&1) },48,"b4ac86fad72c4829"),
            ("glass",m1aWorld(Int3(2,1,1),palette: [a,"minecraft:glass"]) { _,_,_ in 1 },6,"0aeeb33be9923d2b"),
            ("leaves",m1aWorld(Int3(2,1,1),palette: [a,"minecraft:oak_leaves"]) { _,_,_ in 1 },8,"7de0dbc5e7d3c043"),
            ("slab",m1aWorld(Int3(1,1,1),palette: [a,"minecraft:stone_slab[type=top]"]) { _,_,_ in 1 },6,"3196598ce6cef551"),
            ("cross",m1aWorld(Int3(1,1,1),palette: [a,"minecraft:torch"]) { _,_,_ in 1 },2,"3135ad5b8f29c83d"),
            ("odd",m1aWorld(Int3(20,5,3)) { x,y,_ in y == 0 ? 1 : x == 7 && y == 1 ? 9 : 0 },10,"a2ed395fdd09080d")]
        // Raw MeshTests.Hash goldens preserve per-section emission order.
        let exactGoldens: [String: [String]] = [
            "cube": ["f9880038591d5f17"],
            "checker": ["866f11336ccf3c18"],
            "glass": ["1f038712bdfb0d17"],
            "leaves": ["de6ed94d76b38043"],
            "slab": ["c7dbf2ff90cca19b"],
            "cross": ["80a34383df52975b"],
            "odd": ["f7d8efd2d0688adf","9b274904a1e8053f"]]
        for (name,w,quads,hash) in cases {
            let meshes = m1aMeshes(w)
            #expect(meshes.reduce(0) { $0+$1.verts.count/4 } == quads, "\(name)")
            #expect(MeshHash.canonical(meshes) == hash, "\(name)")
            #expect(meshes.map(MeshHash.exact) == exactGoldens[name],"\(name) exact per-section bits")
            #expect(MeshHash.canonical(meshes.reversed()) == hash)
            m1aBenchmark(name,w,specials: true)
        }
    }
    @Test func allSevenSnapshotCSharpGoldens() throws {
        let cases = [
            ("chunk_snapshot.json",32,"a3cfceefca4075e1"),
            ("chunk_snapshot_extras.json",11,"1955d96af9da9a9d"),
            ("chunk_snapshot_sections.json",15,"d6f783f7bc51ac23"),
            ("chunk_snapshot_delta.json",12,"8148ab0980656773"),
            ("chunk_snapshot_sections_light.json",6,"6963698ac8406c45"),
            ("chunk_snapshot_grow.json",25,"bbd67842e5a37ec9"),
            ("chunk_snapshot_shrink.json",6,"a62a38e8d226e2f9")]
        // Indexed in x,y,z section traversal order, matching the C# harness.
        let sectionQuads: [[Int]] = [
            [0,0,0,0,3,3,5,5,0,0,0,0,3,3,5,5],
            [11],
            [10,5],
            [7,5],
            [6],
            [8,8,4,5],
            [6]]
        let exactGoldens: [[String]] = [
            ["f987af2e35fa45f3","f987af2e35fa45f3","f987af2e35fa45f3","f987af2e35fa45f3","10e7438795f8a813","6e013988a6505813","922c4105c630416f","46804a950d0af2b7","f987af2e35fa45f3","f987af2e35fa45f3","f987af2e35fa45f3","f987af2e35fa45f3","9438d24580c193f3","af48765470bceaf3","916bee2aa92c7807","7147f78b1bda7f57"],
            ["472e143db859fab3"],
            ["954127c73b6edc3f","3cbdea1d1e93c13f"],
            ["d3f9bfd00db80beb","493dc8cb6a950527"],
            ["903040d2f4243a97"],
            ["9c2ff20ba7fdd783","2d614fcd50116c23","933ec81377d1e78b","2c97b8d2ecbeca3f"],
            ["08dd444d778cbf77"]]
        let gridGoldens = ["4b57d9fe56548325","764c673f047efd37","6901199ee9705b25","1c4d36b45e34c465","c7e9c7e0ab90af25","42b93b4d952a9325","e80bbd908f9c5325"]
        var base = WorldModel(); base.applySnapshot(try SectionedSnapshot.assemble([m1aFixture("chunk_snapshot_sections.json")]))
        for (fixtureIndex, fixture) in cases.enumerated() {
            let (name,quads,hash) = fixture
            let m = try m1aFixture(name)
            let s = try m.s("encoding") == "sections_v1" ? SectionedSnapshot.assemble([m],current: base) : ChunkSnapshot.from(m)
            var gridHash: UInt64 = 14695981039346656037
            for v in s.grid { for b in [UInt8(truncatingIfNeeded: v),UInt8(truncatingIfNeeded: v >> 8)] { gridHash = (gridHash ^ UInt64(b)) &* 1099511628211 } }
            #expect(String(gridHash,radix: 16) == gridGoldens[fixtureIndex],"\(name) full decoded grid")
            if ProcessInfo.processInfo.environment["M1A_BENCHMARK"] == "1" {
                func decode() throws -> ChunkSnapshot {
                    try m.s("encoding") == "sections_v1" ? SectionedSnapshot.assemble([m],current: base) : ChunkSnapshot.from(m)
                }
                for _ in 0..<10 { _ = try decode() }
                let start = ContinuousClock.now
                var cells = 0
                for _ in 0..<100 { cells += try decode().grid.count }
                let d = start.duration(to: .now).components
                print("M1A \(name) decode_ms=\((Double(d.seconds)*1000+Double(d.attoseconds)/1e15)/100) cells=\(cells)")
                let text = try m1aFixtureText(name)
                func parseDecode() throws -> ChunkSnapshot {
                    guard let object = try Json.parse(text).objectValue else { throw JsonError("expected object") }
                    return try object.s("encoding") == "sections_v1" ? SectionedSnapshot.assemble([object],current: base) : ChunkSnapshot.from(object)
                }
                for _ in 0..<10 { _ = try parseDecode() }
                let parseStart = ContinuousClock.now
                var parsedCells = 0
                for _ in 0..<100 { parsedCells += try parseDecode().grid.count }
                let pd = parseStart.duration(to: .now).components
                print("M1A \(name) parse_decode_ms=\((Double(pd.seconds)*1000+Double(pd.attoseconds)/1e15)/100) cells=\(parsedCells)")
            }
            var w = WorldModel(); w.applySnapshot(s)
            let meshes = m1aMeshes(w,specials: false)
            #expect(meshes.reduce(0) { $0+$1.verts.count/4 } == quads,"\(name)")
            #expect(MeshHash.canonical(meshes) == hash,"\(name)")
            #expect(meshes.map { $0.verts.count/4 } == sectionQuads[fixtureIndex],"\(name) per-section face counts")
            #expect(meshes.map(MeshHash.exact) == exactGoldens[fixtureIndex],"\(name) exact per-section bits")
            m1aBenchmark(name,w,specials: false)
        }
    }
    @Test func terrain64ParityAndTiming() {
        let w = m1aWorld(Int3(64,96,64)) { x,y,z in y < 24+((x*13+z*7)%9) ? 1 : 0 }
        let meshes = m1aMeshes(w)
        #expect(meshes.reduce(0) { $0+$1.verts.count/4 } == 12432)
        #expect(MeshHash.canonical(meshes) == "d1ae5694b2d5ce01")
        m1aBenchmark("terrain64",w,specials: true)
    }
    @Test func noCubesUnknownPaletteAndLeavesOption() {
        let plants = m1aWorld(Int3(16,16,16),palette: ["minecraft:air","minecraft:water","minecraft:short_grass"]) { _,y,_ in y == 0 ? 1 : y == 1 ? 2 : 0 }
        var mesh = MeshData(); GreedyMesher.build(plants,.zero,&mesh); #expect(mesh.verts.isEmpty)
        let odd = m1aWorld(Int3(20,5,3)) { x,y,_ in y == 0 ? 1 : x == 7 && y == 1 ? 9 : 0 }
        GreedyMesher.build(odd,Int3(1,0,0),&mesh)
        #expect(mesh.verts.count/4 == 5 && mesh.verts.map(\.x).max() == 20)
        GreedyMesher.build(odd,.zero,&mesh); #expect(mesh.verts.count/4 == 5)
        let leaves = m1aWorld(Int3(2,1,1),palette: ["minecraft:air","minecraft:oak_leaves"]) { _,_,_ in 1 }
        GreedyMesher.build(leaves,.zero,FlatFaceSource(),&mesh,leavesInner: false)
        #expect(mesh.verts.count/4 == 6 && mesh.transparent.count == 36)
        let flower = m1aWorld(Int3(1,1,1),palette: ["minecraft:air","minecraft:poppy"]) { _,_,_ in 1 }
        GreedyMesher.build(flower,.zero,&mesh); #expect(mesh.verts.isEmpty)
        GreedyMesher.buildSpecials(flower,.zero,&mesh); #expect(mesh.verts.count == 8)
    }
    @Test func sectionMeshMatchesActualCSharpWithMirrorUndone() throws {
        let w = m1aWorld(Int3(20,5,3)) { _,y,_ in y == 0 ? 1 : 0 }
        var data = MeshData(); GreedyMesher.build(w,Int3(1,0,0),&data)
        let section = try #require(SectionMesh.from(data,Int3(1,0,0)))
        // Actual C# SectionMesh.From output, then negate Pos.z/Nz and swap
        // triangle b/c back. Zero signs compare numerically after unmirroring.
        let expected: [[Int]] = [
            [4,0,0,127,0,0,127],[4,1,0,127,0,0,127],[4,1,3,127,0,0,127],[4,0,3,127,0,0,127],
            [0,0,0,0,-127,0,127],[0,0,3,0,-127,0,127],[4,0,3,0,-127,0,127],[4,0,0,0,-127,0,127],
            [0,1,0,0,127,0,127],[0,1,3,0,127,0,127],[4,1,3,0,127,0,127],[4,1,0,0,127,0,127],
            [0,0,0,0,0,-127,127],[4,0,0,0,0,-127,127],[4,1,0,0,0,-127,127],[0,1,0,0,0,-127,127],
            [0,0,3,0,0,127,127],[4,0,3,0,0,127,127],[4,1,3,0,0,127,127],[0,1,3,0,0,127,127]]
        #expect(section.verts.map { [Int($0.pos.x),Int($0.pos.y),Int($0.pos.z),Int($0.nx),Int($0.ny),Int($0.nz),Int($0.nw)] } == expected)
        #expect(section.indices == [0,1,2,0,2,3,4,6,5,4,7,6,8,9,10,8,10,11,12,14,13,12,15,14,16,17,18,16,18,19])
        #expect(section.solid == 30 && section.opaque == 30 && section.quads == 5)
        #expect(section.verts.allSatisfy { $0.color == Color32(125,125,125) })
        #expect(section.verts.map(\.uv) == data.uvs)
        let batch = BatchData.assemble([(section,SIMD3<Float>(0,0,16)),(section,SIMD3<Float>(32,0,0))])
        #expect(batch.min == SIMD3<Float>(0,0,0) && batch.max == SIMD3<Float>(36,1,19))
        #expect(batch.indices.prefix(30) == section.indices[...])
        #expect(Array(batch.indices.suffix(30)) == section.indices.map { $0+20 })
        #expect(batch.drawCalls() == 1 && batch.sections == 2 && batch.quads == 10)
    }
}
